/* ============================================================
   DUOCOM SYSTEMS - SHARED QUOTE TOOLS
   Used by get_quote.html and admin_quote.html.
   Needs prices.js loaded first, and jsPDF + jsPDF-AutoTable for PDFs.
   ============================================================ */

const LOGO_DATA = "data:image/png;base64,";
const LOGO_RATIO = 640 / 290;

const fmtKES = n => 'KES ' + n.toLocaleString('en-KE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const fmtNum = n => n.toLocaleString('en-KE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const pad2 = n => String(n).padStart(2, '0');
const todayStr = () => { const d = new Date(); return `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}/${d.getFullYear()}`; };
const calcTax = (sub, on) => on ? Math.round(sub * SITE_CONFIG.vatRate * 100) / 100 : 0;
const vatLabel = () => `VAT (${Math.round(SITE_CONFIG.vatRate * 100)}%)`;
const safeName = s => (s || '').replace(/[^a-z0-9]+/gi, '_').replace(/^_|_$/g, '') || 'Client';

/* Safe browser storage (never crashes the page if storage is blocked) */
function storeGet(key, fallback) {
    try { const v = localStorage.getItem(key); return v ? JSON.parse(v) : fallback; } catch (e) { return fallback; }
}
function storeSet(key, val) {
    try { localStorage.setItem(key, JSON.stringify(val)); } catch (e) { /* ignore */ }
}

function numberToWords(n) {
    n = Math.round(n);
    if (n === 0) return 'ZERO';
    const ones = ['', 'ONE', 'TWO', 'THREE', 'FOUR', 'FIVE', 'SIX', 'SEVEN', 'EIGHT', 'NINE', 'TEN', 'ELEVEN', 'TWELVE', 'THIRTEEN', 'FOURTEEN', 'FIFTEEN', 'SIXTEEN', 'SEVENTEEN', 'EIGHTEEN', 'NINETEEN'];
    const tens = ['', '', 'TWENTY', 'THIRTY', 'FORTY', 'FIFTY', 'SIXTY', 'SEVENTY', 'EIGHTY', 'NINETY'];
    const b100 = x => x < 20 ? ones[x] : tens[Math.floor(x / 10)] + (x % 10 ? ' ' + ones[x % 10] : '');
    const b1000 = x => x < 100 ? b100(x) : ones[Math.floor(x / 100)] + ' HUNDRED' + (x % 100 ? ' AND ' + b100(x % 100) : '');
    let out = '';
    if (n >= 1e6) { out += b1000(Math.floor(n / 1e6)) + ' MILLION '; n %= 1e6; }
    if (n >= 1e3) { out += b1000(Math.floor(n / 1e3)) + ' THOUSAND '; n %= 1e3; }
    if (n > 0) { out += (out && n < 100 ? 'AND ' : '') + b1000(n); }
    return out.trim();
}
const wordsFor = total => total > 0 ? numberToWords(total) + ' SHILLINGS ONLY' : '\u2014';

/* Totals helper: items = [{qty, rate, amount}] */
function computeTotals(items, taxOn, labour) {
    const sub = items.reduce((s, i) => s + i.amount, 0);
    const tax = calcTax(sub, taxOn);
    const lab = labour || 0;
    return { sub, tax, labour: lab, grand: sub + tax + lab };
}

/* ------------------------------------------------------------
   Build the quotation PDF (same layout as the Duocom quotations).
   q = { title, docNo, dateStr, client:{name,location,contact,service},
         items:[{name,qty,rate,amount}], taxOn, labour, footnote }
   Returns the jsPDF document.
   ------------------------------------------------------------ */
function buildQuotePDF(q) {
    if (!window.jspdf) throw new Error('PDF tool not loaded');
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({ unit: 'mm', format: 'a4' });
    const PURPLE = [107, 79, 160], LTPUR = [237, 231, 246], NAVY = [10, 29, 61], DARK = [45, 55, 72], GRAY = [90, 100, 115], LINE = [185, 185, 195];

    const items = q.items;
    const t = computeTotals(items, q.taxOn, q.labour);

    // Title (shrinks so it never touches the logo)
    let fs = 26;
    doc.setFont('helvetica', 'bold'); doc.setFontSize(fs);
    while (doc.getTextWidth(q.title) > 112 && fs > 14) { fs -= 1; doc.setFontSize(fs); }
    doc.setTextColor(...PURPLE);
    doc.text(q.title, 15, 24);

    // Meta lines
    [['Quotation No #', q.docNo], ['Quotation Date', q.dateStr], ['Phone:', SITE_CONFIG.phones]].forEach(([label, val], i) => {
        const y = 31 + i * 5.5;
        doc.setFont('helvetica', 'normal'); doc.setFontSize(9); doc.setTextColor(...GRAY);
        doc.text(label, 15, y);
        const w = doc.getTextWidth(label + '  ');
        doc.setFont('helvetica', 'bold'); doc.setTextColor(26, 26, 26);
        doc.text(val, 15 + w, y);
    });

    // Logo
    doc.addImage(LOGO_DATA, 'PNG', 137, 9, 58, 58 / LOGO_RATIO);

    // From / For boxes (compact)
    const boxY = 47, boxW = 88, lineH = 3.8;
    const boxes = [
        [15,  'Quotation From', [SITE_CONFIG.companyName, SITE_CONFIG.location, SITE_CONFIG.phones, SITE_CONFIG.email]],
        [107, 'Quotation For',  [q.client.name, q.client.location, q.client.contact, q.client.service].filter(Boolean)]
    ];
    const boxH = 8 + Math.max(...boxes.map(b => b[2].length)) * lineH;
    boxes.forEach(([x, head, lines]) => {
        doc.setFillColor(246, 243, 251); doc.setDrawColor(...LINE); doc.setLineWidth(0.2);
        doc.rect(x, boxY, boxW, boxH, 'FD');
        doc.setFont('helvetica', 'bold'); doc.setFontSize(8.5); doc.setTextColor(...PURPLE);
        doc.text(head, x + 3, boxY + 4.8);
        let y = boxY + 9;
        lines.forEach((l, idx) => {
            doc.setFont('helvetica', idx === 0 ? 'bold' : 'normal');
            doc.setFontSize(8); doc.setTextColor(...DARK);
            doc.text(doc.splitTextToSize(l, boxW - 6)[0], x + 3, y);
            y += lineH;
        });
    });

    // Items table
    const totalQty = items.reduce((s, i) => s + i.qty, 0);
    doc.autoTable({
        startY: boxY + boxH + 6,
        margin: { left: 15, right: 15, bottom: 30 },
        head: [['#', 'Item / Description', 'Qty', 'Rate (KES)', 'Amount (KES)']],
        body: items.map((it, i) => [i + 1 + '.', it.name, String(it.qty), 'KES ' + fmtNum(it.rate), 'KES ' + fmtNum(it.amount)]),
        foot: [['', 'Sub-Total', String(totalQty), '', 'KES ' + fmtNum(t.sub)]],
        showFoot: 'lastPage',
        theme: 'grid',
        styles: { font: 'helvetica', fontSize: 9, cellPadding: 2.6, lineColor: LINE, lineWidth: 0.2, textColor: DARK, valign: 'middle' },
        headStyles: { fillColor: PURPLE, textColor: 255, halign: 'center', fontStyle: 'bold', lineColor: LINE, lineWidth: 0.2 },
        footStyles: { fillColor: 255, textColor: NAVY, fontStyle: 'bold', lineColor: LINE, lineWidth: 0.2 },
        alternateRowStyles: { fillColor: LTPUR },
        columnStyles: {
            0: { halign: 'center', cellWidth: 10 },
            1: { cellWidth: 80 },
            2: { halign: 'center', cellWidth: 18 },
            3: { halign: 'right', cellWidth: 34 },
            4: { halign: 'right', cellWidth: 38, fontStyle: 'bold' }
        },
        didParseCell: d => { if (d.section === 'foot' && d.column.index >= 2) d.cell.styles.halign = d.column.index === 2 ? 'center' : 'right'; }
    });

    // Words + VAT / Labour / Total
    let y = doc.lastAutoTable.finalY + 8;
    if (y > 240) { doc.addPage(); y = 20; }
    const wordLines = doc.splitTextToSize(wordsFor(t.grand).replace('\u2014', 'ZERO SHILLINGS ONLY'), 95);

    doc.setFont('helvetica', 'bold'); doc.setFontSize(9); doc.setTextColor(...DARK);
    doc.text('Total (in words):', 15, y + 3);
    doc.setFont('helvetica', 'normal');
    doc.text(wordLines, 15, y + 8);

    let ty = y + 3;
    doc.setFont('helvetica', 'normal'); doc.setFontSize(10); doc.setTextColor(...DARK);
    if (t.tax > 0) { doc.text(vatLabel(), 125, ty); doc.text('KES ' + fmtNum(t.tax), 195, ty, { align: 'right' }); ty += 6; }
    if (t.labour > 0) { doc.text('Labour', 125, ty); doc.text('KES ' + fmtNum(t.labour), 195, ty, { align: 'right' }); ty += 6; }
    ty -= 1;
    doc.setDrawColor(...PURPLE); doc.setLineWidth(0.6);
    doc.line(125, ty, 195, ty);
    doc.setFont('helvetica', 'bold'); doc.setFontSize(12); doc.setTextColor(...NAVY);
    doc.text('Total (KES)', 125, ty + 7);
    doc.text('KES ' + fmtNum(t.grand), 195, ty + 7, { align: 'right' });

    // Optional footnote
    if (q.footnote) {
        const fy = Math.max(y + 8 + wordLines.length * 4, ty + 7) + 10;
        doc.setFont('helvetica', 'italic'); doc.setFontSize(8); doc.setTextColor(...GRAY);
        doc.text(doc.splitTextToSize(q.footnote, 180), 15, fy);
    }

    // Footer bar on every page
    for (let p = 1; p <= doc.getNumberOfPages(); p++) {
        doc.setPage(p);
        doc.setFillColor(...NAVY);
        doc.rect(15, 279, 180, 9, 'F');
        doc.setFont('helvetica', 'normal'); doc.setFontSize(7.5); doc.setTextColor(255, 255, 255);
        doc.text(`${SITE_CONFIG.companyName.replace('DUOCOM SYSTEMS', 'Duocom Systems')}  |  Nairobi, Kenya  |  ${SITE_CONFIG.phones}  |  ${SITE_CONFIG.email}  |  Commitment and Sacrifice`, 105, 284.5, { align: 'center' });
    }
    return doc;
}

/* Send a message to the Duocom inbox through FormSubmit (no server needed).
   NOTE: the first message ever sent triggers a one-time confirmation email to
   SITE_CONFIG.requestEmail - click the link in it to activate delivery. */
async function sendToInbox(fields) {
    const payload = Object.assign({ _template: 'table', _captcha: 'false' }, fields);
    const res = await fetch('https://formsubmit.co/ajax/' + encodeURIComponent(SITE_CONFIG.requestEmail), {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'Accept': 'application/json' },
        body: JSON.stringify(payload)
    });
    let data = {};
    try { data = await res.json(); } catch (e) { /* non-JSON reply */ }
    if (!res.ok || String(data.success) === 'false') throw new Error(data.message || 'Could not send');
    return data;
}
